 if(isset($_POST['delete_template'])){$id=(int)$_POST['template_id'];$s=$pdo->prepare('SELECT is_default FROM invoice_templates WHERE id=?');$s->execute([$id]);if($s->fetchColumn())throw new RuntimeException('The default template cannot be deleted. Make another template default first.');$pdo->prepare('DELETE FROM invoice_templates WHERE id=?')->execute([$id]);redirect('invoice_templates.php?saved=deleted');}
 if(isset($_POST['save_template'])){$id=(int)($_POST['template_id']??0);$name=trim((string)$_POST['name']);if($name==='')throw new RuntimeException('Template name is required.');$order=json_decode((string)$_POST['block_order'],true);$order=array_values(array_filter(is_array($order)?$order:[],fn($b)=>in_array($b,$allowedBlocks,true)));if(!in_array('items',$order,true)||!in_array('totals',$order,true))throw new RuntimeException('Line items and totals blocks are required.');$labels=[];foreach(['description','quantity','unit_price','tax','amount'] as $key)$labels[$key]=trim((string)$_POST['column_'.$key])?:ucwords(str_replace('_',' ',$key));$logo=$_POST['existing_logo']??null;if(!empty($_FILES['logo']['tmp_name'])){$f=$_FILES['logo'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>2097152)throw new RuntimeException('Logo must be a PNG or JPEG under 2 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=['image/png'=>'png','image/jpeg'=>'jpg'][$mime]??null;if(!$ext||!getimagesize($f['tmp_name']))throw new RuntimeException('Logo must be a valid PNG or JPEG image.');$dir=dirname(__DIR__).'/assets/uploads/invoice-logos';if(!is_dir($dir))mkdir($dir,0755,true);$filename='logo-'.bin2hex(random_bytes(8)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$filename))throw new RuntimeException('Logo upload failed.');$logo='assets/uploads/invoice-logos/'.$filename;}$isDefault=isset($_POST['is_default'])?1:0;$pdo->beginTransaction();if($isDefault)$pdo->exec('UPDATE invoice_templates SET is_default=0');$values=[$name,$isDefault,$logo,$_POST['primary_color'],$_POST['accent_color'],$_POST['font_family'],json_encode($labels),json_encode($order),trim((string)$_POST['bank_details']),trim((string)$_POST['custom_details']),trim((string)$_POST['footer_text'])];if($id){$pdo->prepare('UPDATE invoice_templates SET name=?,is_default=?,logo_path=?,primary_color=?,accent_color=?,font_family=?,column_labels=?,block_order=?,bank_details=?,custom_details=?,footer_text=? WHERE id=?')->execute([...$values,$id]);}else{$pdo->prepare('INSERT INTO invoice_templates(name,is_default,logo_path,primary_color,accent_color,font_family,column_labels,block_order,bank_details,custom_details,footer_text) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute($values);}$pdo->commit();redirect('invoice_templates.php?saved=template');}
