<main class="flex-1 h-screen overflow-y-auto app-scroll"><header class="bg-white border-b px-5 md:px-8 py-5 flex items-center gap-4 sticky top-0 z-10"><button data-sidebar-toggle class="lg:hidden text-2xl">☰</button><div><h2 class="text-2xl font-bold">Invoice template maker</h2><p class="text-sm text-slate-500">Drag blocks, rename columns, add a logo, bank details, colors, and custom content</p></div></header><div class="p-5 md:p-8 max-w-7xl mx-auto"><?php if($error):?><div class="bg-rose-50 border p-4 rounded-xl mb-5"><?=h($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="bg-emerald-50 border p-4 rounded-xl mb-5">Template changes saved.</div><?php endif;?><div class="grid xl:grid-cols-2 gap-7"><form method="post" enctype="multipart/form-data" class="bg-white border rounded-2xl p-6 space-y-5"><?=csrf_field()?><input type="hidden" name="template_id" value="<?=$template['id']?>"><input type="hidden" name="existing_logo" value="<?=h($template['logo_path'])?>"><input type="hidden" name="block_order" id="blockOrder" value="<?=h(json_encode($order))?>"><div class="flex justify-between"><div><h3 class="font-bold text-lg"><?=$template['id']?'Edit template':'Create template'?></h3><p class="text-sm text-slate-500">Changes appear in the preview.</p></div><label class="text-sm flex gap-2 items-center"><input type="checkbox" name="is_default" <?=$template['is_default']?'checked':''?>> Default</label></div><label class="block text-sm">Template name<input name="name" required value="<?=h($template['name'])?>" class="<?=$input?>"></label><div class="grid grid-cols-2 gap-3"><label class="text-sm">Primary color<input type="color" name="primary_color" value="<?=h($template['primary_color'])?>" class="<?=$input?> h-11 p-1 template-control"></label><label class="text-sm">Header color<input type="color" name="accent_color" value="<?=h($template['accent_color'])?>" class="<?=$input?> h-11 p-1 template-control"></label><label class="text-sm">Font<select name="font_family" class="<?=$input?> bg-white template-control"><?php foreach(['Helvetica','Arial','Times New Roman','Georgia','Courier New'] as $f):?><option <?=$template['font_family']===$f?'selected':''?>><?=$f?></option><?php endforeach;?></select></label><label class="text-sm">Logo (PNG/JPEG, 2 MB)<input type="file" name="logo" accept="image/png,image/jpeg" class="<?=$input?>"></label></div><div><p class="text-sm font-semibold">Drag invoice blocks into order</p><div id="blockList" class="space-y-2 mt-2"><?php foreach($order as $block):?><div draggable="true" data-block="<?=$block?>" class="template-block border rounded-lg p-3 bg-slate-50 cursor-move flex justify-between"><span>☰ <?=h($blockNames[$block]??$block)?></span><?php if(!in_array($block,['items','totals'],true)):?><label class="text-xs"><input type="checkbox" class="block-visible" checked> Show</label><?php endif;?></div><?php endforeach;?></div></div><div><p class="text-sm font-semibold">Column names</p><div class="grid grid-cols-2 gap-2 mt-2"><?php foreach(['description','quantity','unit_price','tax','amount'] as $k):?><label class="text-xs"><?=h(ucwords(str_replace('_',' ',$k)))?><input name="column_<?=$k?>" value="<?=h($labels[$k]??'')?>" class="mt-1 w-full border rounded px-2 py-2 column-control" data-column="<?=$k?>"></label><?php endforeach;?></div></div><label class="block text-sm">Bank details<textarea name="bank_details" rows="4" class="<?=$input?> template-text" data-preview="previewBank"><?=h($template['bank_details'])?></textarea></label><label class="block text-sm">Custom details<textarea name="custom_details" rows="3" placeholder="Registration, payment instructions, project information..." class="<?=$input?> template-text" data-preview="previewCustom"><?=h($template['custom_details'])?></textarea></label><label class="block text-sm">Footer / terms<textarea name="footer_text" rows="3" class="<?=$input?> template-text" data-preview="previewNotes"><?=h($template['footer_text'])?></textarea></label><div class="flex gap-2"><button name="save_template" class="brand-bg text-white rounded-lg px-6 py-3 font-semibold flex-1">Save template</button><?php if($template['id']):?><a href="invoice_templates.php" class="border rounded-lg px-4 py-3">New</a><?php endif;?></div></form>
<div class="space-y-6"><section class="bg-slate-200 rounded-2xl p-5"><div id="templatePreview" class="bg-white shadow-lg mx-auto p-8 text-sm" style="min-height:760px;font-family:<?=h($template['font_family'])?>"><div id="previewBlocks"><?php foreach($order as $block):?><div data-preview-block="<?=$block?>" class="preview-block mb-6"><?php if($block==='company'):?><div class="flex justify-between border-b pb-5"><div><?php if($template['logo_path']):?><img src="../<?=h($template['logo_path'])?>" class="max-h-14 max-w-40 mb-2"><?php endif;?><h2 class="text-xl font-black"><?=h(setting($pdo,'company_name','Your Company'))?></h2><p class="text-slate-500"><?=h(setting($pdo,'company_address'))?></p></div><strong class="text-3xl" style="color:<?=$template['primary_color']?>">INVOICE</strong></div><?php elseif($block==='invoice_meta'):?><div class="text-right"><strong>INV-01001</strong><p>Issue: <?=date('M j, Y')?> · Due: <?=date('M j, Y',strtotime('+30 days'))?></p></div><?php elseif($block==='customer'):?><div><p class="text-xs text-slate-400">BILL TO</p><strong>Sample Customer Ltd.</strong><p>customer@example.com<br>Customer address</p></div><?php elseif($block==='items'):?><table class="w-full"><thead style="background:<?=$template['accent_color']?>;color:white"><tr><?php foreach(['description','quantity','unit_price','tax','amount'] as $k):?><th class="p-2 text-left preview-col-<?=$k?>"><?=h($labels[$k]??$k)?></th><?php endforeach;?></tr></thead><tbody><tr class="border-b"><td class="p-2">Professional service</td><td class="p-2">2</td><td class="p-2">$100.00</td><td class="p-2">10%</td><td class="p-2">$220.00</td></tr></tbody></table><?php elseif($block==='totals'):?><div class="ml-auto w-64 space-y-2"><p class="flex justify-between"><span>Subtotal</span><strong>$200.00</strong></p><p class="flex justify-between"><span>Tax</span><strong>$20.00</strong></p><p class="flex justify-between p-3 text-white" style="background:<?=$template['primary_color']?>"><span>Total</span><strong>$220.00</strong></p></div><?php elseif($block==='bank'):?><div><strong>Payment details</strong><p id="previewBank" class="whitespace-pre-line text-slate-600"><?=h($template['bank_details'])?></p></div><?php elseif($block==='custom'):?><p id="previewCustom" class="whitespace-pre-line"><?=h($template['custom_details'])?></p><?php else:?><p id="previewNotes" class="border-t pt-4 text-slate-500 whitespace-pre-line"><?=h($template['footer_text'])?></p><?php endif;?></div><?php endforeach;?></div></div></section><section class="bg-white border rounded-2xl p-6"><h3 class="font-bold mb-3">Saved templates</h3><?php foreach($templates as $t):?><div class="flex justify-between items-center border-t py-3"><div><strong><?=h($t['name'])?></strong><?php if($t['is_default']):?><span class="ml-2 text-xs bg-blue-100 text-blue-700 rounded-full px-2 py-1">Default</span><?php endif;?></div><div class="flex gap-3"><a href="invoice_templates.php?edit=<?=$t['id']?>" class="brand-text font-semibold text-sm">Edit</a><?php if(!$t['is_default']):?><form method="post" onsubmit="return confirm('Delete this template?')"><?=csrf_field()?><input type="hidden" name="template_id" value="<?=$t['id']?>"><button name="delete_template" class="text-rose-600 text-sm">Delete</button></form><?php endif;?></div></div><?php endforeach;?></section></div></div></div></main>
<script>const list=document.getElementById('blockList'),orderInput=document.getElementById('blockOrder'),preview=document.getElementById('previewBlocks');let dragged=null;function sync(){const blocks=[...list.querySelectorAll('.template-block')];orderInput.value=JSON.stringify(blocks.filter(b=>b.querySelector('.block-visible')?.checked!==false).map(b=>b.dataset.block));blocks.forEach(b=>{const p=preview.querySelector(`[data-preview-block="${b.dataset.block}"]`);if(p){preview.append(p);p.style.display=b.querySelector('.block-visible')?.checked===false?'none':''}})}list.addEventListener('dragstart',e=>{dragged=e.target.closest('.template-block')});list.addEventListener('dragover',e=>{e.preventDefault();const target=e.target.closest('.template-block');if(target&&target!==dragged){const rect=target.getBoundingClientRect();list.insertBefore(dragged,e.clientY<rect.top+rect.height/2?target:target.nextSibling);sync()}});list.addEventListener('change',sync);document.querySelectorAll('.column-control').forEach(i=>i.addEventListener('input',()=>document.querySelector('.preview-col-'+i.dataset.column).textContent=i.value));document.querySelectorAll('.template-text').forEach(i=>i.addEventListener('input',()=>document.getElementById(i.dataset.preview).textContent=i.value));document.querySelectorAll('.template-control').forEach(i=>i.addEventListener('input',()=>{document.getElementById('templatePreview').style.fontFamily=document.querySelector('[name=font_family]').value;document.querySelectorAll('[data-preview-block="items"] thead').forEach(e=>e.style.background=document.querySelector('[name=accent_color]').value);document.querySelectorAll('[data-preview-block="totals"] p:last-child').forEach(e=>e.style.background=document.querySelector('[name=primary_color]').value)}));sync();</script><?php require_once 'includes/footer.php';?>
